S.append(dict(slug="versicherungsmakler",es_slug="corredurias-seguros",name="Versicherungsmakler",fini="Versicherungsmakler|ein Versicherungsmaklerbüro|Versicherungsmakler",
h1="Jede vergessene Verlängerung ist ein Kunde, der zu einem anderen Makler geht.",
lead="Abläufe, Schadensfälle, Unterlagen und Vergleiche. Die Betreuung jeder Police hängt zu sehr vom Kalender und vom Gedächtnis einzelner Personen ab.",
cta="Sprechen wir über Ihr Maklerbüro",h2="Was ein Versicherungsmaklerbüro<br>am meisten Zeit kostet.",
pains=[("Verlängerungen und Abläufe","Im Blick behalten, welche Police ausläuft, rechtzeitig informieren und Alternativen vorbereiten, Kunde für Kunde.","Automatische Ablaufhinweise an Kunde und Team so frühzeitig, wie Sie es festlegen, und Nachfassen, bis die Verlängerung abgeschlossen ist.","Automatisierung"),
("Schadenbearbeitung","Der Kunde ruft besorgt an; Daten, Fotos und Berichte müssen gesammelt, an den Versicherer weitergegeben und der Kunde über jeden Schritt informiert werden.","Geführte Schadenmeldung, bei der die Unterlagen nur einmal erfasst werden, und Hinweise an den Kunden bei jeder Statusänderung.","Automatisierung"),
("Kundenunterlagen","Ausweis, Führerschein, Urkunden, Fahrzeugpapiere… Sie anzufordern, entgegenzunehmen und richtig abzulegen, kostet Zeit.","Automatische Anforderung dessen, was fehlt, und geordnete Ablage nach Kunde und Police.","Angewandte KI"),
("Daten verteilt auf Programme und Versicherer","Die Informationen zu jedem Kunden liegen in der Maklersoftware, im E-Mail-Postfach und auf den Portalen der Versicherer.","Die Daten werden verbunden, sodass Ihr Team die vollständige Akte jedes Kunden an einem Ort hat.","Tool-Integration")],
flow=[("45 Tage vorher","Das System erkennt, dass eine Hausratversicherung in anderthalb Monaten ausläuft."),("40 Tage vorher","Der Kunde erhält den Hinweis, der Makler eine Aufgabe, Alternativen zu prüfen."),("30 Tage vorher","Hat der Kunde nicht geantwortet, geht eine Erinnerung raus."),("20 Tage vorher","Der Makler ruft mit dem bereits vorbereiteten Vorschlag an."),("Verlängert","Die Police ist verlängert und der Kunde rechtzeitig betreut.")],
audit="In einer Woche prüfen wir, wie Sie Abläufe und Verlängerungen im Blick behalten, wie Sie Schadensfälle bearbeiten und wo sich die Informationen zu jedem Kunden verteilen."))

S.append(dict(slug="fitness-kursstudios",es_slug="gimnasios-estudios",name="Fitness- und Kursstudios",fini="Fitness- oder Kursstudio|ein Fitness- oder Kursstudio|Fitness- und Kursstudios",
h1="Ein Mitglied, das nicht mehr kommt, ist eine Kündigung, die Sie noch verhindern können.",
lead="Anmeldungen, Kündigungen, Beiträge, Kursbuchungen, Wartelisten und die üblichen Fragen. Wenn alles über den Empfang läuft, hat niemand Zeit zu bemerken, wer gerade wegbleibt.",
cta="Sprechen wir über Ihr Studio",h2="Was ein Fitness- oder Kursstudio<br>am meisten Zeit kostet.",
pains=[("Kündigungen, die niemand kommen sieht","Ein Mitglied kommt nicht mehr, und wenn es kündigt, ist es zu spät.","Ein Hinweis an das Team, wenn ein Mitglied länger nicht da war, und eine Nachricht, um wieder Kontakt aufzunehmen.","Automatisierung"),
("Anfragen neuer Kunden","Preise, Kurszeiten, Probetrainings. Werden sie nicht schnell beantwortet, meldet sich der Interessent woanders an.","Sofortige Antwort mit den Informationen und der Möglichkeit, ein Probetraining zu buchen.","Angewandte KI"),
("Buchungen und Wartelisten","Volle Kurse, kurzfristige Absagen und Plätze, die leer bleiben.","Online-Buchung mit automatischer Warteliste: Sagt jemand ab, wird der Platz dem Nächsten angeboten.","Automatisierung"),
("Beiträge und Rücklastschriften","Zahlungen im Blick behalten, Rücklastschriften nachverfolgen und Tarifwechsel bearbeiten, Mitglied für Mitglied.","Automatische Hinweise auf offene Zahlungen und Nachfassen, bis alles geklärt ist.","Automatisierung")],
flow=[("21:30","Jemand fragt über Instagram nach Pilateskursen."),("21:30","Die Person erhält Kurszeiten, Preise und einen Link, um ein Probetraining zu buchen."),("Nach dem Probetraining","Sie erhält ein Angebot für die Mitgliedschaft."),("Jede Woche","Sie bucht ihre Kurse per Handy; sagt sie ab, geht der Platz an die Warteliste."),("Längere Pause","Kommt sie einige Wochen nicht, erhält das Team einen Hinweis, um wieder Kontakt aufzunehmen.")],
audit="In einer Woche prüfen wir, wie Sie Interessenten betreuen, wie Sie Buchungen, Beiträge und Kündigungen verwalten und welcher Teil der Arbeit am Empfang sich freisetzen lässt."))

S.append(dict(slug="vertrieb-grosshandel",es_slug="distribuidores",name="Vertrieb und Großhandel",fini="Vertrieb|ein Vertriebsunternehmen|Vertriebs- und Großhandelsunternehmen",
h1="Jede von Hand eingetippte Bestellung ist ein möglicher Fehler.",
lead="Bestellungen kommen per WhatsApp, E-Mail und Telefon, jeder Kunde auf seine Weise. Jemand tippt sie von Hand ab, prüft den Bestand in einem anderen Programm und erstellt die Lieferscheine einzeln. Fehler sind teuer, und die Zeit geht für Aufgaben drauf, die nichts verkaufen.",
cta="Sprechen wir über Ihr Unternehmen",h2="Was ein Vertriebsunternehmen<br>am meisten Zeit kostet.",
pains=[("Bestellungen über tausend Kanäle","WhatsApp-Nachrichten, E-Mails, Anrufe und sogar Fotos von einem Notizblock. Jemand muss sie verstehen und eintippen.","Bestellungen werden gelesen, interpretiert und in Ihr System übernommen, bereit zum Prüfen und Bestätigen.","Angewandte KI"),
("Anfragen zu Bestand und Preisen","„Ist das noch da?“, „Was kostet das?“ Jede Frage heißt, in einem anderen Programm nachzusehen und von Hand zu antworten.","Sofortige Antwort mit Bestand und den Konditionen des jeweiligen Kunden, angebunden an Ihr System.","Tool-Integration"),
("Lieferscheine, Rechnungen und Bestätigungen","Die Dokumente erstellen und jede Bestellung dem Kunden bestätigen ist eintönig und fehleranfällig.","Bestätigungen, Lieferscheine und Rechnungen, direkt aus der Bestellung erzeugt, ohne erneutes Eintippen.","Automatisierung"),
("Offene Forderungen","Fälligkeiten prüfen und unbezahlte Rechnungen anmahnen, Kunde für Kunde.","Automatische Fälligkeitshinweise und Nachfassen bei offenen Rechnungen, bis sie bezahlt sind.","Automatisierung")],
flow=[("07:50","Ein Kunde schickt per WhatsApp eine Bestellung mit einer Produktliste."),("07:51","Die Bestellung wird interpretiert und im System erfasst, zur Bestätigung bereit."),("08:30","Das Team prüft sie und bestätigt mit einem Klick; der Kunde erhält die Bestätigung."),("10:00","Der Lieferschein wird automatisch erstellt, und die Ware verlässt das Lager."),("Bei Lieferung","Die Rechnung wird ausgestellt, und der Zahlungseingang ist eingeplant.")],
audit="In einer Woche prüfen wir, wie Bestellungen bei Ihnen ankommen und bearbeitet werden, wie Bestand und Preise abgefragt werden und wie viel Handarbeit zwischen Bestellung und Zahlung steckt."))
